// Sets o.R.Student to related.
// Adds o to related.R.StudentLeads.
func (o *Lead) SetStudent(exec boil.Executor, insert bool, related *User) error {
	var err error
	if insert {
		if err = related.Insert(exec, boil.Infer()); err != nil {
			return errors.Wrap(err, "failed to insert into foreign table")
		}
	}

	updateQuery := fmt.Sprintf(
		"UPDATE \"leads\" SET %s WHERE %s",
		strmangle.SetParamNames("\"", "\"", 1, []string{"student_id"}),
		strmangle.WhereClause("\"", "\"", 2, leadPrimaryKeyColumns),
	)
	values := []any{related.ID, o.ID}

	if boil.DebugMode {
		fmt.Fprintln(boil.DebugWriter, updateQuery)
		fmt.Fprintln(boil.DebugWriter, values)
	}
	if _, err = exec.Exec(updateQuery, values...); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	queries.Assign(&o.StudentID, related.ID)
	if o.R == nil {
		o.R = &leadR{
			Student: related,
		}
	} else {
		o.R.Student = related
	}

	if related.R == nil {
		related.R = &userR{
			StudentLeads: LeadSlice{o},
		}
	} else {
		related.R.StudentLeads = append(related.R.StudentLeads, o)
	}

	return nil
}

// RemoveStudent relationship.
// Sets o.R.Student to nil.
// Removes o from all passed in related items' relationships struct.
func (o *Lead) RemoveStudent(exec boil.Executor, related *User) error {
	var err error

	queries.SetScanner(&o.StudentID, nil)
	if _, err = o.Update(exec, boil.Whitelist("student_id")); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	if o.R != nil {
		o.R.Student = nil
	}
	if related == nil || related.R == nil {
		return nil
	}

	for i, ri := range related.R.StudentLeads {
		if queries.Equal(o.StudentID, ri.StudentID) {
			continue
		}

		ln := len(related.R.StudentLeads)
		if ln > 1 && i < ln-1 {
			related.R.StudentLeads[i] = related.R.StudentLeads[ln-1]
		}
		related.R.StudentLeads = related.R.StudentLeads[:ln-1]
		break
	}
	return nil
}

// AddLeadActivities adds the given related objects to the existing relationships
// of the lead, optionally inserting them as new records.
// Appends related to o.R.LeadActivities.
// Sets related.R.Lead appropriately.
func (o *Lead) AddLeadActivities(exec boil.Executor, insert bool, related ...*LeadActivity) error {
	var err error
	for _, rel := range related {
		if insert {
			rel.LeadID = o.ID
			if err = rel.Insert(exec, boil.Infer()); err != nil {
				return errors.Wrap(err, "failed to insert into foreign table")
			}
		} else {
			updateQuery := fmt.Sprintf(
				"UPDATE \"lead_activities\" SET %s WHERE %s",
				strmangle.SetParamNames("\"", "\"", 1, []string{"lead_id"}),
				strmangle.WhereClause("\"", "\"", 2, leadActivityPrimaryKeyColumns),
			)
			values := []any{o.ID, rel.ID}

			if boil.DebugMode {
				fmt.Fprintln(boil.DebugWriter, updateQuery)
				fmt.Fprintln(boil.DebugWriter, values)
			}
			if _, err = exec.Exec(updateQuery, values...); err != nil {
				return errors.Wrap(err, "failed to update foreign table")
			}

			rel.LeadID = o.ID
		}
	}

	if o.R == nil {
		o.R = &leadR{
			LeadActivities: related,
		}
	} else {
		o.R.LeadActivities = append(o.R.LeadActivities, related...)
	}

	for _, rel := range related {
		if rel.R == nil {
			rel.R = &leadActivityR{
				Lead: o,
			}
		} else {
			rel.R.Lead = o
		}
	}
	return nil
}

// Leads retrieves all the records using an executor.
func Leads(mods ...qm.QueryMod) leadQuery {
	mods = append(mods, qm.From("\"leads\""))
	q := NewQuery(mods...)
	if len(queries.GetSelect(q)) == 0 {
		queries.SetSelect(q, []string{"\"leads\".*"})
	}

	return leadQuery{q}
}

// FindLead retrieves a single record by ID with an executor.
// If selectCols is empty Find will return all columns.
func FindLead(exec boil.Executor, iD string, selectCols ...string) (*Lead, error) {
	leadObj := &Lead{}

	sel := "*"
	if len(selectCols) > 0 {
		sel = strings.Join(strmangle.IdentQuoteSlice(dialect.LQ, dialect.RQ, selectCols), ",")
	}
	query := fmt.Sprintf(
		"select %s from \"leads\" where \"id\"=$1", sel,
	)

	q := queries.Raw(query, iD)

	err := q.Bind(nil, exec, leadObj)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, sql.ErrNoRows
		}
		return nil, errors.Wrap(err, "lms_models: unable to select from leads")
	}

	return leadObj, nil
}

// Insert a single record using an executor.
// See boil.Columns.InsertColumnSet documentation to understand column list inference for inserts.
func (o *Lead) Insert(exec boil.Executor, columns boil.Columns) error {
	if o == nil {
		return errors.New("lms_models: no leads provided for insertion")
	}

	var err error

	nzDefaults := queries.NonZeroDefaultSet(leadColumnsWithDefault, o)

	key := makeCacheKey(columns, nzDefaults)
	leadInsertCacheMut.RLock()
	cache, cached := leadInsertCache[key]
	leadInsertCacheMut.RUnlock()

	if !cached {
		wl, returnColumns := columns.InsertColumnSet(
			leadAllColumns,
			leadColumnsWithDefault,
			leadColumnsWithoutDefault,
			nzDefaults,
		)

		cache.valueMapping, err = queries.BindMapping(leadType, leadMapping, wl)
		if err != nil {
			return err
		}
		cache.retMapping, err = queries.BindMapping(leadType, leadMapping, returnColumns)
		if err != nil {
			return err
		}
		if len(wl) != 0 {
			cache.query = fmt.Sprintf("INSERT INTO \"leads\" (\"%s\") %%sVALUES (%s)%%s", strings.Join(wl, "\",\""), strmangle.Placeholders(dialect.UseIndexPlaceholders, len(wl), 1, 1))
		} else {
			cache.query = "INSERT INTO \"leads\" %sDEFAULT VALUES%s"
		}

		var queryOutput, queryReturning string

		if len(cache.retMapping) != 0 {
			queryReturning = fmt.Sprintf(" RETURNING \"%s\"", strings.Join(returnColumns, "\",\""))
		}

		cache.query = fmt.Sprintf(cache.query, queryOutput, queryReturning)
	}

	value := reflect.Indirect(reflect.ValueOf(o))
	vals := queries.ValuesFromMapping(value, cache.valueMapping)

	if boil.DebugMode {
		fmt.Fprintln(boil.DebugWriter, cache.query)
		fmt.Fprintln(boil.DebugWriter, vals)
	}

	if len(cache.retMapping) != 0 {
		err = exec.QueryRow(cache.query, vals...).Scan(queries.PtrsFromMapping(value, cache.retMapping)...)
	} else {
		_, err = exec.Exec(cache.query, vals...)
	}

	if err != nil {
		return errors.Wrap(err, "lms_models: unable to insert into leads")
	}

	if !cached {
		leadInsertCacheMut.Lock()
		leadInsertCache[key] = cache
		leadInsertCacheMut.Unlock()
	}

	return nil
}

// Update uses an executor to update the Lead.
// See boil.Columns.UpdateColumnSet documentation to understand column list inference for updates.
// Update does not automatically update the record in case of default values. Use .Reload() to refresh the records.
func (o *Lead) Update(exec boil.Executor, columns boil.Columns) (int64, error) {
	var err error
	key := makeCacheKey(columns, nil)
	leadUpdateCacheMut.RLock()
	cache, cached := leadUpdateCache[key]
	leadUpdateCacheMut.RUnlock()

	if !cached {
		wl := columns.UpdateColumnSet(
			leadAllColumns,
			leadPrimaryKeyColumns,
		)
		if len(wl) == 0 {
			return 0, errors.New("lms_models: unable to update leads, could not build whitelist")
		}

		cache.query = fmt.Sprintf("UPDATE \"leads\" SET %s WHERE %s",
			strmangle.SetParamNames("\"", "\"", 1, wl),
			strmangle.WhereClause("\"", "\"", len(wl)+1, leadPrimaryKeyColumns),
		)
		cache.valueMapping, err = queries.BindMapping(leadType, leadMapping, append(wl, leadPrimaryKeyColumns...))
		if err != nil {
			return 0, err
		}
	}

	values := queries.ValuesFromMapping(reflect.Indirect(reflect.ValueOf(o)), cache.valueMapping)

	if boil.DebugMode {
		fmt.Fprintln(boil.DebugWriter, cache.query)
		fmt.Fprintln(boil.DebugWriter, values)
	}
	var result sql.Result
	result, err = exec.Exec(cache.query, values...)
	if err != nil {
		return 0, errors.Wrap(err, "lms_models: unable to update leads row")
	}

	rowsAff, err := result.RowsAffected()
	if err != nil {
		return 0, errors.Wrap(err, "lms_models: failed to get rows affected by update for leads")
	}

	if !cached {
		leadUpdateCacheMut.Lock()
		leadUpdateCache[key] = cache
		leadUpdateCacheMut.Unlock()
	}

	return rowsAff, nil
}

// UpdateAll updates all rows with the specified column values.
func (q leadQuery) UpdateAll(exec boil.Executor, cols M) (int64, error) {
	queries.SetUpdate(q.Query, cols)

	result, err := q.Query.Exec(exec)
	if err != nil {
		return 0, errors.Wrap(err, "lms_models: unable to update all for leads")
	}

	rowsAff, err := result.RowsAffected()
	if err != nil {
		return 0, errors.Wrap(err, "lms_models: unable to retrieve rows affected for leads")
	}

	return rowsAff, nil
}

// UpdateAll updates all rows with the specified column values, using an executor.
func (o LeadSlice) UpdateAll(exec boil.Executor, cols M) (int64, error) {
	ln := int64(len(o))
	if ln == 0 {
		return 0, nil
	}

	if len(cols) == 0 {
		return 0, errors.New("lms_models: update all requires at least one column argument")
	}

	colNames := make([]string, len(cols))
	args := make([]any, len(cols))

	i := 0
	for name, value := range cols {
		colNames[i] = name
		args[i] = value
		i++
	}

	// Append all of the primary key values for each column
	for _, obj := range o {
		pkeyArgs := queries.ValuesFromMapping(reflect.Indirect(reflect.ValueOf(obj)), leadPrimaryKeyMapping)
		args = append(args, pkeyArgs...)
	}

	sql := fmt.Sprintf("UPDATE \"leads\" SET %s WHERE %s",
		strmangle.SetParamNames("\"", "\"", 1, colNames),
		strmangle.WhereClauseRepeated(string(dialect.LQ), string(dialect.RQ), len(colNames)+1, leadPrimaryKeyColumns, len(o)))

	if boil.DebugMode {
		fmt.Fprintln(boil.DebugWriter, sql)
		fmt.Fprintln(boil.DebugWriter, args...)
	}
	result, err := exec.Exec(sql, args...)
	if err != nil {
		return 0, errors.Wrap(err, "lms_models: unable to update all in lead slice")
	}

	rowsAff, err := result.RowsAffected()
	if err != nil {
		return 0, errors.Wrap(err, "lms_models: unable to retrieve rows affected all in update all lead")
	}
	return rowsAff, nil
}

// Upsert attempts an insert using an executor, and does an update or ignore on conflict.
// See boil.Columns documentation for how to properly use updateColumns and insertColumns.
func (o *Lead) Upsert(exec boil.Executor, updateOnConflict bool, conflictColumns []string, updateColumns, insertColumns boil.Columns, opts ...UpsertOptionFunc) error {
	if o == nil {
		return errors.New("lms_models: no leads provided for upsert")
	}

	nzDefaults := queries.NonZeroDefaultSet(leadColumnsWithDefault, o)

	// Build cache key in-line uglily - mysql vs psql problems
	buf := strmangle.GetBuffer()
	if updateOnConflict {
		buf.WriteByte('t')
	} else {
		buf.WriteByte('f')
	}
	buf.WriteByte('.')
	for _, c := range conflictColumns {
		buf.WriteString(c)
	}
	buf.WriteByte('.')
	buf.WriteString(strconv.Itoa(updateColumns.Kind))
	for _, c := range updateColumns.Cols {
		buf.WriteString(c)
	}
	buf.WriteByte('.')
	buf.WriteString(strconv.Itoa(insertColumns.Kind))
	for _, c := range insertColumns.Cols {
		buf.WriteString(c)
	}
	buf.WriteByte('.')
	for _, c := range nzDefaults {
		buf.WriteString(c)
	}
	key := buf.String()
	strmangle.PutBuffer(buf)

	leadUpsertCacheMut.RLock()
	cache, cached := leadUpsertCache[key]
	leadUpsertCacheMut.RUnlock()

	var err error

	if !cached {
		insert, _ := insertColumns.InsertColumnSet(
			leadAllColumns,
			leadColumnsWithDefault,
			leadColumnsWithoutDefault,
			nzDefaults,
		)

		update := updateColumns.UpdateColumnSet(
			leadAllColumns,
			leadPrimaryKeyColumns,
		)

		if updateOnConflict && len(update) == 0 {
			return errors.New("lms_models: unable to upsert leads, could not build update column list")
		}

		ret := strmangle.SetComplement(leadAllColumns, strmangle.SetIntersect(insert, update))

		conflict := conflictColumns
		if len(conflict) == 0 && updateOnConflict && len(update) != 0 {
			if len(leadPrimaryKeyColumns) == 0 {
				return errors.New("lms_models: unable to upsert leads, could not build conflict column list")
			}

			conflict = make([]string, len(leadPrimaryKeyColumns))
			copy(conflict, leadPrimaryKeyColumns)
		}
		cache.query = buildUpsertQueryPostgres(dialect, "\"leads\"", updateOnConflict, ret, update, conflict, insert, opts...)

		cache.valueMapping, err = queries.BindMapping(leadType, leadMapping, insert)
		if err != nil {
			return err
		}
		if len(ret) != 0 {
			cache.retMapping, err = queries.BindMapping(leadType, leadMapping, ret)
			if err != nil {
				return err
			}
		}
	}

	value := reflect.Indirect(reflect.ValueOf(o))
	vals := queries.ValuesFromMapping(value, cache.valueMapping)
	var returns []any
	if len(cache.retMapping) != 0 {
		returns = queries.PtrsFromMapping(value, cache.retMapping)
	}

	if boil.DebugMode {
		fmt.Fprintln(boil.DebugWriter, cache.query)
		fmt.Fprintln(boil.DebugWriter, vals)
	}
	if len(cache.retMapping) != 0 {
		err = exec.QueryRow(cache.query, vals...).Scan(returns...)
		if errors.Is(err, sql.ErrNoRows) {
			err = nil // Postgres doesn't return anything when there's no update
		}
	} else {
		_, err = exec.Exec(cache.query, vals...)
	}
	if err != nil {
		return errors.Wrap(err, "lms_models: unable to upsert leads")
	}

	if !cached {
		leadUpsertCacheMut.Lock()
		leadUpsertCache[key] = cache
		leadUpsertCacheMut.Unlock()
	}

	return nil
}

